162	        let a = generate_pairing_token();
163	        let b = generate_pairing_token();
164	        assert_eq!(a.len(), 32);
165	        assert_ne!(a, b);
166	        assert!(a.chars().all(|c| c.is_ascii_hexdigit()));
167	    }
