      ) : null}

      <SettingsActionRow>
        <Button
          size="sm"
          type="button"
          variant={running ? "destructive" : "default"}
          onClick={() => void toggleServer()}
          disabled={busy || (status ? !status.git_available : true)}
        >
          {busy
            ? running
              ? "Stopping..."
              : "Starting..."
            : running
              ? "Stop server"
              : "Start server"}
        </Button>
        <span className="text-xs text-muted-foreground">
          {busy
            ? running
              ? "Stopping local SSH..."
              : "Starting local SSH..."
            : running
              ? "Running — keep this app open while syncing."
              : "Stopped"}
        </span>
      </SettingsActionRow>

      {error ? <SettingsErrorText>{error}</SettingsErrorText> : null}

      {running ? (
        <div className="space-y-4">
          {status?.host ? null : (
            <SettingsErrorText>
