380	/// Forward the git child's stdout/stderr to the SSH channel, then report its
381	/// exit status and close the channel.
382	fn pump_child_io(session: &mut Session, channel: ChannelId, mut child: Child) {
383	    let handle = session.handle();
384	    tokio::spawn(async move {
385	        let stdout = child.stdout.take();
386	        let stderr = child.stderr.take();
387	
388	        let out_handle = handle.clone();
389	        let out_task = async move {
390	            let Some(mut stdout) = stdout else { return };
391	            let mut buf = vec![0u8; 32 * 1024];
392	            loop {
393	                match stdout.read(&mut buf).await {
394	                    Ok(0) | Err(_) => break,
395	                    Ok(n) => {
396	                        if out_handle
397	                            .data(channel, Vec::from(&buf[..n]))
398	                            .await
399	                            .is_err()
400	                        {
401	                            break;
402	                        }
403	                    }
404	                }
405	            }
406	        };
407	        let err_handle = handle.clone();
408	        let err_task = async move {
409	            let Some(mut stderr) = stderr else { return };
410	            let mut buf = vec![0u8; 8 * 1024];
411	            loop {
412	                match stderr.read(&mut buf).await {
413	                    Ok(0) | Err(_) => break,
414	                    Ok(n) => {
415	                        if err_handle
416	                            .extended_data(channel, 1, Vec::from(&buf[..n]))
417	                            .await
418	                            .is_err()
419	                        {
420	                            break;
421	                        }
422	                    }
423	                }
424	            }
425	        };
426	        tokio::join!(out_task, err_task);
427	
428	        let code = child
429	            .wait()
430	            .await
431	            .ok()
432	            .and_then(|status| status.code())
433	            .unwrap_or(1) as u32;
434	        eprintln!("[local-sync] git process finished with exit code {code}");
