    activeNote,
    setActiveNote,
    clearDraft,
    clearNote,
    renamingFolder,
    setRenamingFolder,
    renameValue,
    setRenameValue,
  });

  return (
    <NotesTreeContext.Provider
      value={{
        tree,
        treeData,
        flatItems,
        visibleItems,
        orderedIds,
        flatItemById,
        expanded,
        setExpanded,
        notes,
        allNotes,
        notePreviews,
        allNotePreviews,
        activeNode,
        visibleNavigationItems,
        feedVisibleNavigationItems,
        feedTreeData,
        feedNodeById,
